    const GR = '#cbc6bb', GRD = '#b6b1a6', WIN = {c:'#262b31', m:1, fh:3.9, cw:1.8}, SLATE = '#5a6160', COP = '#6f8f86', STEP = '#bdb8ad';
    const P = RG[k].ring.map(p => p.slice());
    const m = B.p(GR), d = B.p(GRD), w = B.p(WIN), sl = B.p(SLATE);
    const Y1 = F + 9.0, Y2 = F + 26.5, Y3 = F + 29.2, Y4 = F + 34.2, YM = F + 35.4, YR = F + 46.6;
    prismP(m, P, S.lo, YM);
    for (let y = F + 0.9; y < Y1 - 0.5; y += 0.75) corP(d, P, y, 0.12, 0.07);   // rustication
    corP(d, P, Y1 - 0.2, 0.7, 0.45);                                            // base cornice
    corP(d, P, Y2, 0.6, 0.3); corP(m, P, Y2 + 0.6, 1.4, 0.15); corP(d, P, Y3 - 0.6, 0.7, 0.9);  // entablature
    corP(d, P, Y4 - 0.3, 0.5, 0.35); corP(m, P, Y4 + 0.2, 0.5, 1.1); corP(d, P, YM - 0.7, 0.35, 0.8);  // attic cornice
    const front = e => e.nz > 0.7 || e.nx > 0.7;     // Chambers and Centre Street facades get the free columns
    baysP(P, 4.1, e => {
      const ent = e.nz > 0.7 && Math.abs(e.x) < 9;
      if (ent) wa(w, e, F + 0.3, F + 7.6, 2.6, 0.06); else { wa(w, e, F + 1.0, F + 4.0, 1.6, 0.06); wq(w, e, F + 5.0, F + 7.6, 1.6, 0.06); }
      for (const [y0, y1] of [[Y1 + 1.6, Y1 + 4.6], [Y1 + 6.6, Y1 + 9.8], [Y1 + 11.6, Y1 + 15.0]]){ wq(w, e, y0, y1, 1.75, 0.06); wb(d, e, y1 + 0.1, y1 + 0.45, 2.5, 0.3); }
      wq(w, e, Y3 + 1.1, Y4 - 1.0, 1.6, 0.06);                        // attic windows
      if (front(e) && e.k > 0) { const x = e.x - e.ux*e.bw/2 + e.nx*1.1, z = e.z - e.uz*e.bw/2 + e.nz*1.1;
        colP(m, x, z, Y1 + 0.5, Y2 - Y1 - 0.5, 0.62, 10); boxP(d, 1.7, 1.0, 1.7, x, Y2 - 1.0, z, Math.atan2(-e.uz, e.ux)); boxP(d, 1.6, 0.5, 1.6, x, Y1 + 0.5, z, Math.atan2(-e.uz, e.ux)); }
      else wb(m, e, Y1 + 0.5, Y2, 0.9, 0.35, -e.bw/2);
      wb(m, e, Y3, Y4, 0.7, 0.25, -e.bw/2);                           // attic pilaster strips
    }, null, 6);
    // projecting entablature over the free columns (Chambers and Centre)
    { const a = 1.9; abox(d, -27, -14.2, Y2, Y3 - 0.6, 22.8, 22.8 + a); abox(d, 13.6, 27, Y2, Y3 - 0.6, 22.8, 22.8 + a); abox(d, -14.4, 13.8, Y2, Y3 - 0.6, 24.4, 24.4 + a); abox(d, 29.5, 29.5 + a, Y2, Y3 - 0.6, -21, 21); }
    // mansard: steep slate slopes, flat crown with a cresting rail, dormers and chimneys
    const Pm = offP(P, -0.6), Pt = offP(P, -6.2);
    { const n = Pm.length; for (let i = 0; i < n; i++){ const a = Pm[i], b = Pm[(i+1) % n], c = Pt[(i+1) % n], e2 = Pt[i];
        quadP(sl, [a[0], YM, a[1]], [b[0], YM, b[1]], [c[0], YR - 1.4, c[1]], [e2[0], YR - 1.4, e2[1]]); }
      const Pc = offP(P, -7.2); prismP(sl, Pt.map(p => p), YR - 1.4, YR - 0.6); flatP(sl, Pt, YR - 0.6);
      lineRingP(B.p(COP), Pt, YR - 0.2, 0.12); void Pc; }
    baysP(Pm, 8.2, e => { const x = e.x - e.nx*1.6, z = e.z - e.nz*1.6, ry = Math.atan2(-e.uz, e.ux);
      boxP(m, 2.6, 4.2, 2.2, x, YM + 1.6, z, ry); wq(w, {x:x + e.nx*1.11, z:z + e.nz*1.11, ux:e.ux, uz:e.uz, nx:e.nx, nz:e.nz}, YM + 2.2, YM + 5.0, 1.4, 0);
      const t = [x + e.nx*1.1, z + e.nz*1.1], b0 = [x - e.nx*1.1, z - e.nz*1.1];
      triP(d, [t[0] - e.ux*1.5, YM + 5.8, t[1] - e.uz*1.5], [t[0] + e.ux*1.5, YM + 5.8, t[1] + e.uz*1.5], [t[0], YM + 7.2, t[1]]);
      quadP(d, [t[0] - e.ux*1.5, YM + 5.8, t[1] - e.uz*1.5], [t[0], YM + 7.2, t[1]], [b0[0], YM + 7.2, b0[1]], [b0[0] - e.ux*1.5, YM + 5.8, b0[1] - e.uz*1.5]);
      quadP(d, [t[0], YM + 7.2, t[1]], [t[0] + e.ux*1.5, YM + 5.8, t[1] + e.uz*1.5], [b0[0] + e.ux*1.5, YM + 5.8, b0[1] + e.uz*1.5], [b0[0], YM + 7.2, b0[1]]); }, null, 6);
