    // corner pedestals with the sculpture groups (abstract stone masses) on the attic of the Chambers / Centre fronts
    for (const [x, z] of [[-25.5, 23.6], [25.5, 23.6], [30.2, -19.5], [30.2, 19.5], [-9.5, 25.4], [9.5, 25.4]]){
      boxP(m, 3.0, 1.6, 2.4, x, Y4 + 0.6, z, 0); const r = LMCTX.rng;
      for (let i = 0; i < 3; i++) segP(d, [x + (i - 1)*0.8, Y4 + 2.2, z], [x + (i - 1)*0.6 + (r() - 0.5)*0.4, Y4 + 4.6 + r()*0.8, z + (r() - 0.5)*0.4], 0.42, 5, 0.25); }
    // entrance steps on Chambers Street
