    for (let i = 0; i < 10; i++){ const z = zA + (zB - zA)*i/9; colP(m, xF, z, Y1, 17.6, 0.85, 12); boxP(d, 2.3, 1.2, 2.3, xF, Y1 + 16.4, z, 0); }
    for (const z of [zA, zB]) for (const x of [-42.4]){ colP(m, x, z, Y1, 17.6, 0.85, 12); boxP(d, 2.3, 1.2, 2.3, x, Y1 + 16.4, z, 0); }
    const YE = Y1 + 17.6;
    abox(d, -48.0, -36.0, YE, YE + 1.4, -21.4, 21.4); abox(m, -48.2, -36.0, YE + 1.4, YE + 3.0, -21.6, 21.6); abox(d, -48.6, -36.0, YE + 3.0, YE + 3.6, -22.0, 22.0);
    { const y0 = YE + 3.6, y1 = YE + 10.6, x0 = -48.6, x1 = -36.0; triP(m, [x0, y0, -22], [x0, y0, 22], [x0, y1, 0]); quadP(B.p(ROOF), [x0, y0, -22], [x0, y1, 0], [x1, y1, 0], [x1, y0, -22]); quadP(B.p(ROOF), [x0, y1, 0], [x0, y0, 22], [x1, y0, 22], [x1, y1, 0]);
      triP(d, [x0 + 1.2, y0 + 0.6, -18.5], [x0 + 1.2, y0 + 0.6, 18.5], [x0 + 1.2, y1 - 1.4, 0]); }
