    for (const x of [-37.2, 34.2]) abox(m, x, x + 3.0, YR, YR + 4.4, -11.0, 11.0);
    // roof: parapet, plant screen, aviation lights
    prismP(m, offP(P, -0.5), YR, YR + 1.6, true); flatP(B.p('#77716a'), offP(P, -0.5), YR + 0.3);
    abox(d, -18, 22, YR, YR + 4.0, -10, 10);
    for (const [x, z] of [[-35, -11], [-35, 11], [35, -11], [35, 11]]) boxP(B.p(RED), 0.6, 0.6, 0.6, x, YR + 1.6, z, 0);
