// ---------------- 200 West Street (2005-10, Pei Cobb Freed): the 228 m glass tower in Battery Park City — the main body with the
// long convex curved west face, the lower shoulders (208 m) on West Street (local +x) and on Murray Street (local -z), the
// low wings on the west and on Vesey Street (local +z); clear pale-blue glass wrapped by thin white horizontal sunshade
// bands on every floor, a slim parapet, lit office floors at night. Built straight from the mapped building parts.
LANDMARKS.ny200west = {zh:'西街200号', en:'200 West Street', cat:'new', r:72, h:229,
  lt:{m:1, c:'#ffe9c8', k:0.8},
  build(){
    const g = new THREE.Group(), B = mkB(), k = 'ny200west', S = siteOf(k), F = S.F;
    const GL = {c:'#8fa6b4', m:1, fh:4.3, cw:1.5}, FIN = {c:'#e4e8ea', m:0, lc:'#dfe8ff', lk:0.6}, SP = '#c9cdd0', RF = '#6f7377', DK = '#2c343c';
    const gl = B.p(GL), fin = B.p(FIN);
    const parts = RG[k].parts.map(q => [q[0], q[1], q[2].map(p => p.slice())]).sort((a, b) => b[1] - a[1]);
    for (const [, top, R] of parts){
      const yt = F + top - (top > 100 ? 0 : 0), yb = S.lo;
      prismP(gl, R, yb, yt - 1.4);
      prismP(B.p(SP), R, yt - 1.4, yt, true); flatP(B.p(RF), R, yt - 0.3);
      // sunshade bands every floor (thin, 0.45 m out)
      const n0 = top > 100 ? 4.3 : 4.6;
      for (let y = F + 6.2; y < yt - 2; y += n0) corP(fin, R, y, 0.22, 0.45);
      // a few vertical mullion lines (every ~9 m)
      mullP(fin, R, F + 6.0, yt - 1.4, 9.0, 0.25, 0.05);
      // tall glass lobby: the lowest 6 m darker
      corP(B.p(DK), R, F, 6.0, -0.4);
    }
    // the roof plant screens and the aviation lights on the main body
    const main = parts[0][2]; const bb = bbP(main);
    abox(B.p(SP), -14, 14, F + 228, F + 229.0, -42, -6);
    for (const [x, z] of [[-18, -48], [20, -40], [4, 22]]) boxP(B.p({c:'#a01010', glow:'#ff2a1a', gk:2}), 0.5, 0.5, 0.5, x, F + (z > 20 ? 208 : 228) + 0.2, z, 0);
    void bb;
    B.flush(g); return g; }};
place('ny200west');

// ---------------- Jefferson Market Library (1874-77, Frederick Clarke Withers / Vaux & Withers): High Victorian Gothic former
