    // steep slate roof: lofted inset rings (hip-like), coloured in two slates
    const r1 = offP(P, -2.8), r2 = offP(P, -4.9), R = [];
    loftP(B.p(SLT), [P.map(p => [p[0], YE + 0.1, p[1]]), r1.map(p => [p[0], YE + 6.0, p[1]])]);
    loftP(B.p(SLT2), [r1.map(p => [p[0], YE + 6.0, p[1]]), r2.map(p => [p[0], YE + 8.6, p[1]])]);
    flatP(B.p(SLT2), r2, YE + 8.6); void R;
