    baysP(T, 3.3, e => { wa(w, e, F + 13.6, F + 16.6, 0.8, 0.09, 0, true); wa(w, e, F + 17.6, F + 20.6, 0.8, 0.09, 0, true); }, null, 2);
    corP(s, T, F + 26.0, 0.6, 0.5);
