    abox(s, tx - tw/2 - 0.3, tx + tw/2 + 0.3, F + 31.0, F + 31.35, tz - tw/2 - 0.3, tz + tw/2 + 0.3);
    balP(B.p(BLK), offP(T, 0.25), F + 31.35, 1.0, 0.45);
    for (const [x, z] of T) latheP(s, [[0.35, F + 31.3], [0.3, F + 34.5], [0.01, F + 37.5]], x, z, 4, PI/4);
    // spire: steep pyramid in slate with gablets, copper finial
