    { const o = B.p(SLT), y0 = F + 36.1, y1 = F + 44.6, h = tw/2 - 0.5, C = [[tx - h, y0, tz - h], [tx + h, y0, tz - h], [tx + h, y0, tz + h], [tx - h, y0, tz + h]], tp = [tx, y1, tz];
      for (let i = 0; i < 4; i++) triP(o, C[i], C[(i+1) % 4], tp); }
    latheP(B.p(COP), [[0.25, F + 44.4], [0.1, F + 46.3], [0.01, F + 46.6]], tx, tz, 6);
