    // west front: aisle ends with pinnacles
    for (const z of [-8.5, 8.5]) { abox(m, -21.9, -20.3, lo, YA + 2.6, z - 0.7, z + 0.7); latheP(d, [[0.65, YA + 2.6], [0.01, YA + 7.2]], -21.1, z, 4, PI/4); }
